def lattice(n, stripes, marks):
    g = [[0]*n for _ in range(n)]
    for p in stripes:
        g[p] = [8]*n
        for r in range(n): g[r][p] = 8
    cuts = [p for p in stripes]
    spans = []
    start = 0
    for p in cuts + [n]:
        if start < p: spans.append((start,p))
        start = p+1
    for color, ri, ci in marks:
        r0,r1 = spans[ri]; c0,c1 = spans[ci]
        g[(r0+r1-1)//2][(c0+c1-1)//2] = color
    return g, spans

